insert into public.methodology_versions (version, params, params_hash, status, notes, frozen_at, published_at) values
  ('2026.1', '{"description": "First ElectraLens methodology. Thresholds are proposals, tuned on synthetic data only, and frozen once a run uses them.", "fdr_q": "0.05", "min_part_electors": 50, "rules": {"R01": {"version": "1.0.0"}, "R02": {"matching": "phonetic_key_v1", "max_age_gap": 2, "version": "1.0.0"}, "R03": {"max_age": 110, "min_age": 18, "version": "1.0.0"}, "R04": {"tolerance_years": 1, "version": "1.0.0"}, "R05": {"min_count": 20, "min_effect": "2.0", "version": "1.0.0"}, "R06": {"min_count": 20, "min_effect": "2.0", "version": "1.0.0"}, "R07": {"version": "1.0.0"}, "R08": {"min_electors": 20, "percentile": "0.999", "version": "1.0.0"}, "R09": {"min_count": 10, "min_effect": "1.5", "min_shift_per_1000": 50, "version": "1.0.0"}, "R10": {"min_share": "0.05", "percentile": "0.95", "version": "1.0.0"}, "R11": {"min_count": 10, "min_deletions": 20, "min_effect": "2.0", "version": "1.0.0"}, "R12": {"min_count": 10, "min_effect": "2.0", "version": "1.0.0"}}, "signal": {"moderate": {"effect": "2.0", "q": "0.01"}, "strong": {"effect": "3.0", "q": "0.001"}, "weak": {"effect": "1.5", "q": "0.05"}}, "version": "2026.1"}'::jsonb, 'f468a887e74d21e45f38d7a013ead418f10bda857ae499aa50d5d21f4aeccce1', 'published', 'First ElectraLens methodology. Thresholds are proposals, tuned on synthetic data only, and frozen once a run uses them.', now(), now());
